-- Check how many traffic rows are missing before updating.
SELECT COUNT(*) AS missing_traffic_rows
FROM tmp_ap_user_count_august_2026 staged
LEFT JOIN ap_traffic_logs traffic
    ON traffic.id_project <=> @id_project
   AND traffic.id_lokasi = @id_lokasi
   AND UPPER(TRIM(traffic.nama_lantai)) = staged.nama_lantai
   AND traffic.tanggal = STR_TO_DATE(CONCAT('2026-08-', LPAD(staged.hari, 2, '0')), '%Y-%m-%d')
WHERE traffic.id IS NULL;

START TRANSACTION;

UPDATE ap_traffic_logs traffic
JOIN tmp_ap_user_count_august_2026 staged
    ON traffic.id_project <=> @id_project
   AND traffic.id_lokasi = @id_lokasi
   AND UPPER(TRIM(traffic.nama_lantai)) = staged.nama_lantai
   AND traffic.tanggal = STR_TO_DATE(CONCAT('2026-08-', LPAD(staged.hari, 2, '0')), '%Y-%m-%d')
SET traffic.jumlah_user = staged.jumlah_user,
    traffic.updated_at = NOW();

COMMIT;

-- Expected result: 589 rows with jumlah_user filled for August 1-31.
SELECT COUNT(*) AS imported_rows, SUM(jumlah_user) AS total_jumlah_user
FROM ap_traffic_logs
WHERE id_project <=> @id_project
  AND id_lokasi = @id_lokasi
  AND tanggal BETWEEN '2026-08-01' AND '2026-08-31'
  AND nama_lantai IN (
      'LANTAI 2', 'LANTAI 3', 'LANTAI 5', 'LANTAI 8', 'LANTAI 9',
      'LANTAI 18', 'LANTAI 26', 'LANTAI 27', 'LANTAI 28', 'LANTAI 29',
      'LANTAI 30', 'LANTAI 31', 'LANTAI 32', 'LANTAI 33', 'LANTAI 37',
      'LANTAI 38', 'LANTAI 39', 'LANTAI 40', 'LANTAI 41'
  )
  AND jumlah_user IS NOT NULL;

DROP TEMPORARY TABLE tmp_ap_user_count_august_2026;
